export interface ConnectorConfig {
  asanaPersonalAccessToken: string
  asanaWorkspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  first_name: string
  last_name: string
  email: string
  answers: Record<string, string>
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  notes: string
  workspace: {
    gid: string
    resource_type: string
    name: string
  }
}

export interface HandleResult {
  taskId: string
  taskName: string
}

function validatePayload(payload: unknown): asserts payload is JotformSubmissionPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.first_name !== 'string' || p.first_name.trim() === '') {
    throw new Error('Missing required field: first_name')
  }
  if (typeof p.last_name !== 'string' || p.last_name.trim() === '') {
    throw new Error('Missing required field: last_name')
  }
  if (typeof p.email !== 'string' || p.email.trim() === '') {
    throw new Error('Missing required field: email')
  }
  if (!p.answers || typeof p.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
}

function formatAnswers(answers: Record<string, string>): string {
  return Object.entries(answers)
    .map(([key, value]) => `${key}=${value}`)
    .join(', ')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const { asanaPersonalAccessToken, asanaWorkspaceGid, fetch: injectedFetch } = config
  const fetchFn = injectedFetch ?? fetch

  const taskName = `${payload.first_name.trim()} ${payload.last_name.trim()}`.trim()
  const answersText = formatAnswers(payload.answers)
  const taskNotes = `Email: ${payload.email.trim()}\nAnswers: ${answersText}`

  const requestBody = {
    data: {
      name: taskName,
      notes: taskNotes,
      workspace: asanaWorkspaceGid,
    },
  }

  const response = await fetchFn('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${asanaPersonalAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    const errorText = await response.text().catch(() => '')
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} for POST https://app.asana.com/api/1.0/tasks - ${errorText}`
    )
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
  }
}

